 function Query([string]$sql){$prior=$env:MYSQL_PWD;try{$env:MYSQL_PWD=$connection[3];$rows=@($sql|& C:/wamp64/bin/mariadb/mariadb11.4.9/bin/mysql.exe --host=$($connection[0]) --port=$($connection[1]) --user=$($connection[2]) --database=$($connection[4]) --batch --raw --skip-column-names);if($LASTEXITCODE){throw 'Awakening TEMP query failed'};$rows}finally{$env:MYSQL_PWD=$prior}}
 $tables=@('creature','creature_template','smart_scripts','npc_spellclick_spells','spell_script_names','conditions');$sql='';$reset=''
