 if($VerifyLiveData){$sql+=@"
SET @released_awake := EXISTS(SELECT 1 FROM updates WHERE name='2026_10_28_03_stromkar_awakening.sql' AND hash='$sha' AND state='RELEASED') AND EXISTS(SELECT 1 FROM saved_creature_template WHERE entry=103398 AND ScriptName='npc_stromkar_awakening');
