SELECT 103398,0,0,1,73,100,1,0,0,80,103398,2,1,0,0,0,0,'Spell Click - Run TS' WHERE @released_awake
UNION ALL SELECT 103398,0,1,2,61,100,1,0,0,205,92,49101,7,0,0,0,0,'Link - CSC' WHERE @released_awake
