UNION ALL SELECT 103398,9,1,0,0,100,1,0,0,41,0,0,1,0,0,0,0,'TS - Despawn' WHERE @released_awake;
"@}
 $snapshot="SELECT 'TAG-actor',creature_template.* FROM creature_template ORDER BY entry;SELECT 'TAG-smart',smart_scripts.* FROM smart_scripts ORDER BY entryorguid,source_type,id;SELECT 'TAG-script',spell_script_names.* FROM spell_script_names ORDER BY spell_id,ScriptName;SELECT 'TAG-cond',conditions.* FROM conditions ORDER BY SourceTypeOrReferenceId,SourceGroup,SourceEntry,ElseGroup,ConditionTypeOrReference;"
 $sql+="$reset`nSELECT 'baseline-click-credit',COUNT(*) FROM smart_scripts WHERE entryorguid=103398 AND source_type=0 AND id=1 AND action_type=205 AND action_param1=92 AND action_param2=49101;`n$migration`n$($snapshot.Replace('TAG','first'))`n$migration`n$($snapshot.Replace('TAG','second'))`nSELECT 'binding',AIName,ScriptName FROM creature_template WHERE entry=103398;SELECT 'row',ElseGroup,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,NegativeCondition FROM conditions WHERE SourceTypeOrReferenceId=17 AND SourceEntry=206361 ORDER BY ConditionTypeOrReference;SELECT 'combat-before',saved_smart_scripts.* FROM saved_smart_scripts WHERE entryorguid=104276 ORDER BY source_type,id;SELECT 'combat-after',smart_scripts.* FROM smart_scripts WHERE entryorguid=104276 ORDER BY source_type,id;SELECT 'click-before',saved_npc_spellclick_spells.* FROM saved_npc_spellclick_spells;SELECT 'click-after',npc_spellclick_spells.* FROM npc_spellclick_spells;`n"
 $variants=[ordered]@{'custom-initial'="UPDATE creature_template SET ScriptName='custom' WHERE entry=103398;";'custom-combat'="UPDATE creature_template SET ScriptName='custom' WHERE entry=104276;";'custom-click'='UPDATE npc_spellclick_spells SET cast_flags=2;';'wrong-phase'="UPDATE creature SET PhaseId='5737';";'custom-delay'='UPDATE smart_scripts SET event_param1=1 WHERE entryorguid=103398 AND source_type=9 AND id=0;';'custom-link'='UPDATE smart_scripts SET link=0 WHERE entryorguid=103398 AND source_type=0 AND id=0;';'missing-event'='DELETE FROM smart_scripts WHERE entryorguid=103398 AND source_type=0 AND id=1;';'extra-event'="INSERT INTO smart_scripts(entryorguid,source_type,id,comment) VALUES(103398,0,99,'custom');";'custom-cast-script'="INSERT INTO spell_script_names VALUES(206360,'custom');";'custom-stun-gate'='INSERT INTO conditions(SourceTypeOrReferenceId,SourceEntry,ConditionTypeOrReference,ConditionValue1) VALUES(17,206361,22,1);'}
 foreach($name in $variants.Keys){$sql+="$reset`n$($variants[$name])`n$($snapshot.Replace('TAG',"$name-before"))`n$migration`n$($snapshot.Replace('TAG',"$name-after"))`n"}
 $rows=Query $sql;[IO.File]::WriteAllLines("$out/sql-evidence.tsv",[string[]]$rows)
 function Snapshot([string]$tag){[string]::Join("`n",[string[]]@($rows|Where-Object {$_ -like "$tag`t*"}|ForEach-Object {$_.Substring($tag.Length+1)}))}
 foreach($kind in @('actor','smart','script','cond')){if((Snapshot "first-$kind") -cne (Snapshot "second-$kind")){throw "Non-idempotent $kind"};foreach($name in $variants.Keys){if((Snapshot "$name-before-$kind") -cne (Snapshot "$name-after-$kind")){throw "Custom variant changed $name/$kind"}}}
 foreach($kind in @('combat','click')){if((Snapshot "$kind-before") -cne (Snapshot "$kind-after")){throw "Changed native $kind"}}
 if($rows -notcontains "baseline-click-credit`t1" -or $rows -notcontains "binding`tSmartAI`tnpc_stromkar_awakening"){throw 'Original click counterfactual/new binding missing'}
 $data=@($rows|Where-Object {$_ -like "row`t*"}|ForEach-Object {$_.Substring(4)});$expected=@("0`t9`t0`t41105`t0`t0`t0","0`t15`t0`t1`t0`t0`t0","0`t22`t0`t1539`t0`t0`t0","0`t32`t0`t16`t0`t0`t0","0`t36`t0`t0`t0`t0`t0","0`t44`t0`t1037`t7`t0`t0");if(Compare-Object $data $expected){throw 'Native late-stun gates differ'};[IO.File]::WriteAllLines("$out/rows.tsv",[string[]]$data)
 $vs=& "${env:ProgramFiles(x86)}/Microsoft Visual Studio/Installer/vswhere.exe" -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath
 $facingFlags=''
