 $hostSource=$hostSource.Replace("        scenarioManager.scenario.step=10;`n        aura=false;",'').Replace("        scenarioManager.scenario.step=10;`r`n        aura=false;",'')
 [IO.File]::WriteAllText("$out/ArrivalHost.inc",$hostSource)
 $source=Get-Content "$repo/src/server/game/Conditions/ConditionMgr.cpp" -Raw
