 [IO.File]::WriteAllText("$out/Conditions.inc",$cases);[IO.File]::WriteAllText("$out/ElseGroups.inc",(Section $source 'bool ConditionMgr::IsObjectMeetToConditionList(' 'bool ConditionMgr::IsObjectMeetToConditions(WorldObject* object,'));[IO.File]::WriteAllText("$out/NotGroupedConditions.inc",(Section $source 'ConditionList ConditionMgr::GetConditionsForNotGroupedEntry(' 'ConditionList ConditionMgr::GetConditionsForSpellClickEvent('))
 $source=Get-Content "$repo/src/server/game/Spells/Spell.cpp" -Raw;[IO.File]::WriteAllText("$out/CastConditions.inc",(Section $source '    ConditionSourceInfo condInfo = ConditionSourceInfo(m_caster);' "    // Don't check explicit target for passive spells"))
 $source=Get-Content "$repo/src/server/game/Movement/MovementGenerators/PointMovementGenerator.cpp" -Raw;[IO.File]::WriteAllText("$out/Arrival.inc",$source.Substring($source.IndexOf('void EffectMovementGenerator::Finalize(')))
 [IO.File]::WriteAllText("$out/arrival.cmd","@echo off`ncall `"$vs/VC/Auxiliary/Build/vcvars64.bat`" >nul`ncd /d `"$out`"`ncl /nologo /EHsc /std:c++17 /fsanitize=address /Zi /I`"$out`" `"$PSScriptRoot/StromkarAwakeningArrivalTest.cpp`" /Fe:arrival.exe /Fo:arrival.obj`nif errorlevel 1 exit /b 1`narrival.exe rows.tsv`nexit /b %errorlevel%`n")
