 $effects=Get-Content "$repo/src/server/game/Spells/SpellEffects.cpp" -Raw;$motion=Get-Content "$repo/src/server/game/Movement/MotionMaster.cpp" -Raw
 $spellSource=Get-Content "$repo/src/server/game/Spells/Spell.cpp" -Raw;$init=Section $spellSource 'void Spell::InitExplicitTargets(' 'void Spell::SelectExplicitTargets('
