 [IO.File]::WriteAllText("$out/SelfTarget.inc",(Section $effects '    JumpArrivalCastArgs arrivalCast;' "`n}`n`nvoid Spell::CalculateJumpSpeeds"));[IO.File]::WriteAllText("$out/BaselineSelfTarget.inc",(Section $baselineEffects '    JumpArrivalCastArgs arrivalCast;' "`n}`n`nvoid Spell::CalculateJumpSpeeds"))
 [IO.File]::WriteAllText("$out/LaunchGuard.inc",(Section $motion '    bool skyholdDeparture = arrivalCast' '    uint32 arrivalSpellId = 0;'));[IO.File]::WriteAllText("$out/BaselineLaunchGuard.inc",(Section $baselineMotion '    bool skyholdDeparture = arrivalCast' '    uint32 arrivalSpellId = 0;'))
 [IO.File]::WriteAllText("$out/motion.cmd","@echo off`ncall `"$vs/VC/Auxiliary/Build/vcvars64.bat`" >nul`ncd /d `"$out`"`ncl /nologo /EHsc /std:c++17 /fsanitize=address /Zi /I`"$out`" `"$PSScriptRoot/StromkarAwakeningMotionTest.cpp`" /Fe:motion.exe /Fo:motion.obj`nif errorlevel 1 exit /b 1`nmotion.exe`nexit /b %errorlevel%`n")
