 if($VerifyLiveData){$live=Query "SELECT 'release',hash,state FROM updates WHERE name='2026_10_28_03_stromkar_awakening.sql'; SELECT 'binding',AIName,ScriptName FROM creature_template WHERE entry=103398;SELECT 'old',COUNT(*) FROM smart_scripts WHERE entryorguid=103398;SELECT 'script',ScriptName FROM spell_script_names WHERE spell_id=206360;SELECT 'row',ElseGroup,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,NegativeCondition FROM conditions WHERE SourceTypeOrReferenceId=17 AND SourceEntry=206361 ORDER BY ConditionTypeOrReference;";foreach($e in @("release`t$sha`tRELEASED","binding`tSmartAI`tnpc_stromkar_awakening","old`t0","script`tspell_stromkar_opening_recoil")){if($live -notcontains $e){throw "Live awakening mismatch $e"}};if(Compare-Object $data @($live|Where-Object {$_ -like "row`t*"}|ForEach-Object {$_.Substring(4)})){throw 'Live stun gates differ'}}
 if($VerifyReleaseBinary){if(!$ReleaseDirectory){$ReleaseDirectory="$repo/build-extractors/bin/Release"};$prior=$env:LEGION_RELEASE_DIRECTORY;$py=$env:PYTHONPATH;try{if($ReleaseDirectory){$env:LEGION_RELEASE_DIRECTORY=$ReleaseDirectory};$env:PYTHONPATH="$repo/.codex/pe-review-deps";& C:/Users/Admin/.cache/codex-runtimes/codex-primary-runtime/dependencies/python/python.exe "$PSScriptRoot/verify_stromkar_awakening_release.py" $ReleaseDirectory;if($LASTEXITCODE){throw 'Linked awakening PE failed'}}finally{$env:LEGION_RELEASE_DIRECTORY=$prior;$env:PYTHONPATH=$py}}
